option.value:
body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    margin: 0;
    padding: 0;
    background: #ada2f8;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
}

.container {
    background-color: white;
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
    padding: 60px;
    text-align: center;
    width: 80%;
}

table {
    width: 100%;
}

th, td {
    border: 1px solid #e0e0e0;
    padding: 15px;
    text-align: left;
}

th {
    background: #764ba2;
    color: white;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.9em;
    letter-spacing: 0.5px;
}

a {
    color: #667eea;
    text-decoration: none;
    font-weight: 600;
    transition: color 0.3s ease;
}

.no-events {
    padding: 40px;
    text-align: center;
    background-color: #f8f9fa;
    border-radius: 8px;
    margin-top: 20px;
}

.no-events p {
    color: #666;
    font-size: 1.2em;
    margin: 0;
}

.event-description {
    max-width: 300px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.field {
    text-align: start;
    padding: .5rem 0;
}

.label {
    font-weight: bold;
    padding: .2rem 0;
}

.marks-list {
    margin: .2rem 0;
}

.marks-list li {
    padding: .5rem 0;
}

.form-row {
    display: flex;
    flex-direction: column;
    margin-bottom: 1rem;
    text-align: start;
}

label {
    font-weight: 700;
    margin-bottom: .3rem;
    color: #333;
}

input[type="text"], textarea {
    padding: .6rem;
    border-radius: 8px;
    border: 1px solid #ddd;
    width: 100%;
    max-width: 100%;
    min-width: 100%;
    box-sizing: border-box;
}

textarea {
    min-height: 3rem;
}

.actions {
    display: flex;
    gap: 1rem;
    margin-top: 1rem;
    justify-content: center;
}

.btn {
    padding: .6rem 1rem;
    border-radius: 8px;
    border: none;
    cursor: pointer;
    font-weight: 700;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.btn-primary {
    background: #304087;
    color: white;
    transition: .3s;
}

.btn-primary:hover {
    background: #4a5ebc;
    color: white;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px solid #e0e0e0;
}

.info {
    color: #667eea;
    transition: .3s;
}

.info:hover {
    color: #8498f1;
}

.danger {
    color: #e04b4b;
    transition: .3s;
}

.danger:hover {
    color: #ec6969;
}

.error {
    color: #b00020;
    margin-bottom: 1rem;
}

.top-actions {
    display: flex;
    justify-content: flex-end;
    margin-bottom: 1rem;
}

